const fs = require('fs');
const path = require('path');

if (process.argv.length !== 4) {
  console.log('Usage: ' + process.argv[1] + ' package.json path/to/silk/sdk/glue');
  process.exit(1);
}

var fileName = process.argv[2];
var baseDir = process.argv[3];

function rewriteDeps(dependencies) {
  if (!dependencies) {
    return;
  }
  Object.keys(dependencies).forEach(function(name) {
    var version = dependencies[name];
    if (!version.startsWith('file:')) {
      return;
    }
    var relativePath = version.slice('file:'.length);
    dependencies[name] = 'file:' + path.resolve(baseDir, relativePath);
  });
}

var package = JSON.parse(fs.readFileSync(fileName), 'utf-8');
rewriteDeps(package.dependencies);
rewriteDeps(package.devDependencies);
// Explicitly unlink the possibly symlinked package.json, so we don't
// change the original copy that's version-controlled.
fs.unlinkSync(fileName);
fs.writeFileSync(
  fileName,
  JSON.stringify(package, null, 2),
  {encoding: 'utf-8'}
);
process.exit(0);
